Here is a complete, production-grade Pulumi `ComponentResource` implementation in TypeScript that wraps the S3 bucket, RDS PostgreSQL instance, and IAM role. It adheres strictly to your canonical spec and uses stack configuration for environment differentiation.

### `component.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

/**
 * AppInfrastructure ComponentResource
 * Wraps S3, RDS, and IAM resources with environment-aware configuration.
 */
export class AppInfrastructure extends pulumi.ComponentResource {
  readonly bucket: aws.s3.BucketV2;
  readonly db: aws.rds.Instance;
  readonly role: aws.iam.Role;
  readonly dbConnectionString: pulumi.Output<string>;

  constructor(name: string, opts?: pulumi.ComponentResourceOptions) {
    super("custom:app-infrastructure", name, undefined, opts);

    // 1. Stack Configuration & Environment Detection
    const cfg = new pulumi.Config("app-infra");
    const env = cfg.get("environment") || pulumi.getStack();
    const isProd = env === "prod";

    // Secrets: Pulumi ConfigSecret (encrypted at rest, never plaintext in Git)
    const dbPassword = cfg.requireSecret("dbPassword");
    const dbSubnetIds = cfg.getObject<string[]>("dbSubnetIds") ?? ["subnet-dev-1", "subnet-dev-2"];

    // 2. S3 Bucket: Versioning, Encryption, No Public Access
    this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
      bucket: `app-assets-${env}-${pulumi.getStack()}`,
      tags: { Environment: env, ManagedBy: "pulumi" },
    }, { parent: this });

    new aws.s3.BucketVersioningV2(`${name}-versioning`, {
      bucket: this.bucket.id,
      versioningConfiguration: { status: "Enabled" },
    }, { parent: this });

    new aws.s3.BucketServerSideEncryptionConfiguration(`${name}-encryption`, {
      bucket: this.bucket.id,
      rules: [{
        applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
      }],
    }, { parent: this });

    new aws.s3.BucketPublicAccessBlock(`${name}-public-access`, {
      bucket: this.bucket.id,
      blockPublicAcls: true,
      blockPublicPolicy: true,
      ignorePublicAcls: true,
      restrictPublicBuckets: true,
    }, { parent: this });

    // 3. RDS PostgreSQL: Deletion Protection, Backup, No Public Access
    const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnet`, {
      subnetIds: dbSubnetIds,
      tags: { Environment: env },
    }, { parent: this });

    this.db = new aws.rds.Instance(`${name}-db`, {
      engine: "postgres",
      engineVersion: "15.4",
      instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
      allocatedStorage: 20,
      dbSubnetGroupName: dbSubnetGroup.name,
      multiAz: isProd,
      storageEncrypted: isProd,
      deletionProtection: true,
      backupRetentionPeriod: 7,
      publiclyAccessible: false,
      dbPort: 5432,
      dbName: "appdb",
      username: "appadmin",
      password: dbPassword,
      tags: { Environment: env },
    }, { parent: this });

    // Composite secret for downstream consumption (e.g., Kubernetes SecretStore)
    this.dbConnectionString = pulumi.interpolate`postgresql://${this.db.username}:${dbPassword}@${this.db.endpoint}:5432/${this.db.name}`;

    // 4. IAM Role: Least Privilege, Env-Specific Trust Policy
    const trustPolicy = isProd
      ? {
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Principal: { Federated: "arn:aws:iam::oidc-provider/token.actions.githubusercontent.com" },
            Action: "sts:AssumeRoleWithWebIdentity",
            Condition: { StringEquals: { "token.actions.githubusercontent.com:aud": "sts.amazonaws.com" } },
          }],
        }
      : {
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Principal: { Service: "ec2.amazonaws.com" },
            Action: "sts:AssumeRole",
          }],
        };

    this.role = new aws.iam.Role(`${name}-service-role`, {
      assumeRolePolicy: JSON.stringify(trustPolicy),
      tags: { Environment: env },
    }, { parent: this });

    // Least-privilege inline policy (no wildcards)
    const rolePolicy = pulumi.all([this.bucket.arn, this.db.arn]).apply(([bucketArn, dbArn]) => {
      return JSON.stringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Action: ["s3:GetObject", "s3:PutObject", "s3:ListBucket", "s3:GetBucketLocation"],
            Resource: [bucketArn, pulumi.interpolate`${bucketArn}/*`],
          },
          {
            Effect: "Allow",
            Action: ["rds-db:connect", "rds:DescribeDBInstances"],
            Resource: [dbArn],
          },
        ],
      });
    });

    new aws.iam.RolePolicy(`${name}-role-policy`, {
      role: this.role.name,
      policy: rolePolicy,
    }, { parent: this });

    // Register component outputs
    this.registerOutputs({
      bucketName: this.bucket.bucket,
      dbEndpoint: this.db.endpoint,
      roleArn: this.role.arn,
      dbConnectionString: this.dbConnectionString,
    }, undefined, true);

    this.registerResourceModules(this.name, {
      "app-infra": [this.bucket, this.db, this.role],
    });
  }
}
```

### Stack Configuration Files

#### `Pulumi.dev.yaml`
```yaml
config:
  app-infra:environment: dev
  app-infra:dbSubnetIds:
    - subnet-0a1b2c3d4e5f6a7b8
    - subnet-0b2c3d4e5f6a7b8c9
  aws:region: us-east-1
```

#### `Pulumi.prod.yaml`
```yaml
config:
  app-infra:environment: prod
  app-infra:dbSubnetIds:
    - subnet-prod-1a2b3c4d
    - subnet-prod-5e6f7g8h
  aws:region: us-east-1
```

#### Secrets Injection (Git-agnostic)
Pulumi handles encryption automatically. To add secrets without plaintext in Git:
```bash
pulumi config set app-infra:dbPassword --secret
```
*(Use `pulumi login` with a cloud backend, `sops` provider, or `gpg` for local encryption. Secrets are encrypted at rest in the state backend.)*

### Usage in `index.ts`
```typescript
import { AppInfrastructure } from "./component";

// Instantiate component per stack
const infra = new AppInfrastructure("core-infra");

// Export for downstream stacks (e.g., Kubernetes, ALB)
export const bucketName = infra.bucketName;
export const dbEndpoint = infra.dbEndpoint;
export const roleArn = infra.roleArn;
export const dbConnectionString = infra.dbConnectionString;
```

### ✅ Acceptance Criteria Mapping

| Criterion | Implementation |
|---|---|
| **Bucket**: versioning, AES-256/KMS, no public access | `BucketVersioningV2`, `BucketServerSideEncryptionConfiguration`, `BucketPublicAccessBlock` with all `true` flags |
| **RDS**: deletion protection, backup ≥7d, no public access | `deletionProtection: true`, `backupRetentionPeriod: 7`, `publiclyAccessible: false` |
| **Secret**: never plaintext, encrypted at rest | `cfg.requireSecret("dbPassword")` + Pulumi backend encryption (sops/GPG/cloud-native) |
| **IAM**: least privilege
